	_, err := io.WriteString(w, trailAgentHelp)
	return err
}

// upsertManagedBlock returns existing with the managed block inserted or
// refreshed. If the markers are already present, the region between them
// (inclusive) is replaced; otherwise the block is appended. Content outside the
// markers is preserved verbatim so the agent's other memory is never clobbered.
func upsertManagedBlock(existing []byte, block string) []byte {
	text := string(existing)
	start := strings.Index(text, trailGuideStartMarker)
	end := strings.Index(text, trailGuideEndMarker)
	if start >= 0 && end >= start {
		endClose := end + len(trailGuideEndMarker)
		return []byte(text[:start] + block + text[endClose:])
	}
	if len(text) == 0 {
		return []byte(block + "\n")
	}
	if !strings.HasSuffix(text, "\n") {
		text += "\n"
	}
	return []byte(text + "\n" + block + "\n")
